#!/bin/bash
# T-0075-AC3: the form/wizard archetype generalises past its exemplars. Two
# throwaway FW modules, in feature/zz_probe/:
#   zz_fw_probe  a three-step wizard (name, notes, review) with a flow result
#   zz_fw_plain  a one-step form with a flow result
# (specs: tool/mcgen/test/fixtures/zz_fw_*/mcgen.yaml). Each is
#   1. generated by `mcgen gen`;
#   2. analysed with mc_analysis (`bazel build --config=lint`), with no issue;
#   3. tested under Bazel: its BDD suite (the template steps over the mocked
#      backend), flow-scope and architecture tests;
# and deleted again, whatever happens. Never committed.
#   tool/mcgen/tool/T-0075-AC3_fw_probe.sh [--out FILE] [--role R]
# MC_BAZEL_STARTUP (e.g. "--output_base=/tmp/mc-ob-T-0075-engineer") picks the
# Bazel server, as for every tool/checks script.
set -uo pipefail
source "$(dirname "${BASH_SOURCE[0]}")/../../checks/lib.sh"
cd "$REPO" || exit 2
if [[ -e feature/zz_probe ]]; then
  echo "feature/zz_probe exists; remove it first (this script owns it)" >&2
  exit 2
fi
read -r -a DART <<< "${MC_DART:-fvm dart}"
log="$(mktemp)"
trap 'rm -rf "$REPO/feature/zz_probe"; rm -f "$log"' EXIT
rc=0
step() {  # step <label> <command...>
  local label="$1"; shift
  if "$@" > "$log" 2>&1; then
    report "- PASS: $label"
  else
    report "- **FAIL**: $label" '```' "$(plain "$log" | tail -30)" '```'
    rc=1
  fi
}
report "# T-0075-AC3: throwaway form/wizard modules" "" "HEAD \`$(git rev-parse --short HEAD)\`" ""
for m in zz_fw_probe zz_fw_plain; do
  P=feature/zz_probe/$m
  report "## $m"
  mkdir -p "$P"
  cp "tool/mcgen/test/fixtures/$m/mcgen.yaml" "$P/mcgen.yaml"
  step "mcgen gen $m" "${DART[@]}" run tool/mcgen/bin/mcgen.dart gen "$m"
  report "  - $(find "$P" -type f | wc -l | tr -d ' ') files generated"
  step "mcgen gen --check $m (idempotent)" "${DART[@]}" run tool/mcgen/bin/mcgen.dart gen --check "$m"
  step "bazel build --config=lint //$P/... (mc_analysis, no issue)" bzw build --config=lint "//$P/..."
  step "bazel test //$P/... (uncached)" bzw test --nocache_test_results --test_output=errors "//$P/..."
  if [[ -f "bazel-testlogs/$P/bdd_test/test.log" ]]; then
    report "  - BDD scenarios: $(grep -c '^  PASS ' "bazel-testlogs/$P/bdd_test/test.log") passed, $(grep -c '^  FAIL ' "bazel-testlogs/$P/bdd_test/test.log") failed"
  fi
  for t in architecture_test bdd_test flow_scope_test; do
    if bzw test "//$P:$t" 2>&1 | grep -q "PASSED"; then
      report "  - //$P:$t PASSED"
    else
      report "  - **//$P:$t not PASSED**"
      rc=1
    fi
  done
done
finish T-0075-AC3 "$rc"
